fn is_palindrome(text: Vec<char>) -> bool {
    // Helper function to convert uppercase ASCII letters to lowercase.
    fn ascii_to_lowercase(c: char) -> char {
        if c >= 'A' && c <= 'Z' {
            // Convert uppercase ASCII letter to lowercase
            ((c as u8) + 32) as char
        } else {
            c
        }
    }

    let len = text.len();
    // Compare characters from both ends moving towards center
    for i in 0..len / 2 {
        let left_char = ascii_to_lowercase(text[i]);
        let right_char = ascii_to_lowercase(text[len - 1 - i]);
        if left_char != right_char {
            return false;
        }
    }
    true
}